        st = q.popleft()
        sid = id_of[st]
        nxt_ids = []
        for c in range(26):
            # compute new row via LCS recurrence
            # st[i] = LCS(T_prefix, S[:i+1]); st[-1] conceptually 0 for i=-1
            new = []
            prev_new = 0  # new_{i-1}
            prev_old = 0  # d_{i-1}
            for i in range(N):
                di = st[i]
                val = di
                if prev_new > val:
                    val = prev_new
                if S[i] == chr(ord('a') + c):
                    cand = prev_old + 1
                    if cand > val:
                        val = cand
                new.append(val)
                prev_old = di
                prev_new = val
            nt = tuple(new)
            if nt not in id_of:
                id_of[nt] = len(states)
                states.append(nt)
                q.append(nt)
            nxt_ids.append(id_of[nt])
        trans.append(nxt_ids)

    # Aggregate transitions: per state, dict next_id -> count of letters
    agg = []
    for nxt_ids in trans:
        d = {}
        for nid in nxt_ids:
            d[nid] = d.get(nid, 0) + 1
        agg.append(list(d.items()))

    # M-step counting DP
    cur = [0] * len(states)
    cur[0] = 1
    for _ in range(M):
        nxt = [0] * len(states)
        for sid, cnt in enumerate(cur):
            if cnt:
                for nid, mult in agg[sid]:
                    nxt[nid] = (nxt[nid] + cnt * mult) % MOD
        cur = nxt

    ans = [0] * (N + 1)
    for sid, st in enumerate(states):
        ans[st[-1]] = (ans[st[-1]] + cur[sid]) % MOD

    sys.stdout.write(' '.join(map(str, ans)) + '\n')

main()

from typing import List


class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(L: int, R: int) -> int:
            # Number of (a, b) with 1 <= a <= L, 1 <= b <= R, a + b <= k + 1
            s = k + 1
            if L + R <= s:
                return L * R
            # a from 1..L, b_max = min(R, s - a), clamped at 0
            # Split: a <= s - R -> b_max = R ; s - R < a < s -> b_max = s - a ; a >= s -> 0
            total = 0
            # Region 1: a in [1, min(L, s - R)] contributes R each
            a1 = min(L, s - R)
            if a1 > 0:
                total += a1 * R
            # Region 2: a in [max(1, s - R + 1), min(L, s - 1)] contributes (s - a)
            lo = max(1, s - R + 1)
            hi = min(L, s - 1)
            if lo <= hi:
                m = hi - lo + 1
                total += m * s - (lo + hi) * m // 2
            return total

        def extremum_sum(arr: List[int], is_max: bool) -> int:
            # left[i]: distance to previous index that "blocks" attribution
            # For max: previous greater-or-equal on left, strictly greater on right
            # For min: previous less-or-equal on left, strictly less on right
            left = [0] * n
            right = [0] * n
            stack = []
            for i in range(n):
                if is_max:
                    while stack and arr[stack[-1]] < arr[i]:
                        stack.pop()
                else:
                    while stack and arr[stack[-1]] > arr[i]:
                        stack.pop()
                left[i] = i - stack[-1] if stack else i + 1
                stack.append(i)
            stack = []
            for i in range(n - 1, -1, -1):
                if is_max:
                    while stack and arr[stack[-1]] <= arr[i]:
                        stack.pop()
                else:
                    while stack and arr[stack[-1]] >= arr[i]:
                        stack.pop()
                right[i] = stack[-1] - i if stack else n - i
                stack.append(i)
            total = 0
            for i in range(n):
                total += arr[i] * count_pairs(left[i], right[i])
            return total

        return extremum_sum(nums, True) + extremum_sum(nums, False)

import sys


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])
    max_m = N * (N - 1) // 2
    half = N // 2

    # Binomial coefficients modulo P.
    # All arguments are <= 435 << P, so Pascal's rule is valid mod P.
    C = [[0] * (max_m + 1) for _ in range(max_m + 1)]
    for n in range(max_m + 1):
        C[n][0] = 1 % P
        C[n][n] = 1 % P
        for k in range(1, n):
            C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % P

    # cross[a][b][t] = coeff of x^t in ((1+x)^a - 1)^b.
    # This is the generating function for edges between a previous BFS layer
    # of size a and a new layer of size b, where every new vertex has at
    # least one edge to the previous layer.
    cross = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        base = [0] * (max_m + 1)
        for t in range(1, a + 1):
            base[t] = C[a][t]

        cross[a][0] = [1] + [0] * max_m
        for b in range(1, N + 1):
            prev = cross[a][b - 1]
            cur = [0] * (max_m + 1)
            max_prev = a * (b - 1)
            for i in range(max_prev + 1):
                vi = prev[i]
                if vi:
                    lim = min(a, max_m - i)
                    for j in range(1, lim + 1):
                        cur[i + j] = (cur[i + j] + vi * base[j]) % P
            cross[a][b] = cur

    # trans[a][b] = polynomial for appending a new layer of size b after a
    # previous layer of size a:
    #   ((1+x)^a - 1)^b * (1+x)^(b choose 2)
    trans = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            cr = cross[a][b]
            w = b * (b - 1) // 2
            out = [0] * (max_m + 1)
            max_cr = a * b
            for i in range(max_cr + 1):
                vi = cr[i]
                if vi:
                    lim = min(w, max_m - i)
                    for j in range(lim + 1):
                        out[i + j] = (out[i + j] + vi * C[w][j]) % P
            trans[a][b] = out

    # DP over exact BFS layers from vertex 1.
    # State: (used_vertices, even_vertices, last_layer_size, parity_of_next_layer)
    # Value: truncated generating function by number of edges.
    #
    # parity_of_next_layer = 1 means the next layer is odd (L1, L3, ...),
    # parity_of_next_layer = 0 means the next layer is even (L2, L4, ...).
    dp = {(1, 1, 1, 1): [1] + [0] * max_m}

    for used in range(1, N + 1):
        max_used_edges = used * (used - 1) // 2
        for even in range(1, min(half, used) + 1):
            for last in range(1, used + 1):
                for parity in (0, 1):
                    poly = dp.get((used, even, last, parity))
                    if poly is None:
                        continue

                    rem = N - used
                    for b in range(1, rem + 1):
                        neven = even + (b if parity == 0 else 0)
                        if neven > half:
                            continue
                        if used + b == N and neven != half:
                            continue

                        # Choose the labels of the b vertices in the new layer.
                        choose = C[rem][b]
                        tr = trans[last][b]
                        max_tr = last * b + b * (b - 1) // 2

                        res = [0] * (max_m + 1)
                        for i in range(max_used_edges + 1):
                            vi = poly[i]
                            if vi:
                                lim = min(max_tr, max_m - i)
                                for j in range(lim + 1):
                                    tj = tr[j]
                                    if tj:
                                        res[i + j] = (res[i + j] + vi * tj) % P

                        if choose != 1:
                            for i in range(max_m + 1):
                                res[i] = (res[i] * choose) % P

                        key = (used + b, neven, b, parity ^ 1)
                        old = dp.get(key)
                        if old is None:
                            dp[key] = res
                        else:
                            for i in range(max_m + 1):
                                s = old[i] + res[i]
                                if s >= P:
                                    s -= P
                                old[i] = s

    ans = [0] * (max_m + 1)
    for (used, even, last, parity), poly in dp.items():
        if used == N and even == half:
            for m in range(max_m + 1):
                s = ans[m] + poly[m]
                if s >= P:
                    s -= P
                ans[m] = s

    sys.stdout.write(" ".join(str(ans[m] % P) for m in range(N - 1, max_m + 1)))


if __name__ == "__main__":
    main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    n = int(data[pos]); p = int(data[pos + 1]); pos += 2
    A = [[int(data[pos + i * n + j]) % p for j in range(n)] for i in range(n)]
    pos += n * n

    # matrix multiply mod p, O(n^3)
    def matmul(X, Y):
        Z = [[0] * n for _ in range(n)]
        for i in range(n):
            Xi = X[i]
            Zi = Z[i]
            for k in range(n):
                x = Xi[k]
                if x:
                    Yk = Y[k]
                    xv = x
                    for j in range(n):
                        Zi[j] = (Zi[j] + xv * Yk[j]) % p
        return Z

    def matpow(M, e):
        R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        B = [row[:] for row in M]
        while e:
            if e & 1:
                R = matmul(R, B)
            e >>= 1
            if e:
                B = matmul(B, B)
        return R

    K = 0
    for i in range(n):
        Ai = A[i]
        for j in range(n):
            if Ai[j] == 0:
                K += 1

    if p == 2:
        # unique filling: zeros become 1; answer is B^2 mod 2
        B = [[A[i][j] if A[i][j] else 1 for j in range(n)] for i in range(n)]
        C = matmul(B, B)
    else:
        # S = (-1)^K * ( A^p + loop-correction + (p==3 ? non-loop-correction : 0) ) mod p
        C = matpow(A, p)
        # loop zeros e=(u,u): contribute A E_uu + E_uu A
        # (the (p-2)*E F E term vanishes since A[u][u] = 0)
        for u in range(n):
            if A[u][u] == 0:
                Au = A[u]
                Cu = C[u]
                for j in range(n):
                    Cu[j] = (Cu[j] + Au[j]) % p      # E_uu A: row u += row u of A
                for i in range(n):
                    C[i][u] = (C[i][u] + A[i][u]) % p  # A E_uu: col u += col u of A
        # non-loop zeros contribute only when p == 3: A[v][u] * E_{u,v}
        if p == 3:
            for u in range(n):
                Au = A[u]
                Cu = C[u]
                for v in range(n):
                    if u != v and Au[v] == 0:
                        Cu[v] = (Cu[v] + A[v][u]) % p
        if K & 1:
            # multiply by (-1)^K = -1 mod p
            for i in range(n):
                Ci = C[i]
                for j in range(n):
                    if Ci[j]:
                        Ci[j] = p - Ci[j]

    out = sys.stdout
    for i in range(n):
        out.write(' '.join(map(str, C[i])) + '\n')

main()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def canAchieve(k: int) -> bool:
            flips_needed = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                run_length = j - i
                flips_needed += run_length // (k + 1)
                if flips_needed > numOps:
                    return False
                i = j
            return flips_needed <= numOps

        left, right = 1, n
        while left < right:
            mid = (left + right) // 2
            if canAchieve(mid):
                right = mid
            else:
                left = mid + 1
        return left

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            # iterative path compression
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # Key fact: if a | L and b | L, then lcm(a, b) | L, so lcm(a, b) <= L.
        # Hence for every L <= threshold, all present values dividing L form a
        # clique. Conversely, any edge (a, b) with lcm(a, b) = L0 <= threshold
        # is witnessed at L = L0 since both a and b divide L0.
        #
        # rep[L] = index of the first present divisor of L encountered; every
        # later present divisor of L is unioned with it, building the clique.
        #
        # Values > threshold can never have an edge (lcm(a,b) >= max(a,b)),
        # so they stay as singleton components automatically.
        rep = {}
        for i, v in enumerate(nums):
            if v > threshold:
                continue
            for L in range(v, threshold + 1, v):
                r = rep.get(L)
                if r is None:
                    rep[L] = i
                else:
                    union(i, r)

        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)
